    bq(U, EX3, 'EX5.3', '2(vii)', 'Find the square root of (x<sup>2</sup> + 1/x<sup>2</sup>)<sup>2</sup> &minus; 8(x<sup>2</sup> + 1/x<sup>2</sup>) + 16 by division method.', 'x<sup>2</sup> &minus; 4 + 1/x<sup>2</sup>',
       '= (x<sup>2</sup> + 1/x<sup>2</sup> &minus; 4)<sup>2</sup>, so the square root is x<sup>2</sup> &minus; 4 + 1/x<sup>2</sup>.', 122),
    bq(U, EX3, 'EX5.3', '2(viii)', 'Find the square root of x<sup>6</sup> + 1/x<sup>6</sup> &minus; 4(x<sup>3</sup> + 1/x<sup>3</sup>) + 6 (x &ne; 0) by division method.', 'x<sup>3</sup> &minus; 2 + 1/x<sup>3</sup>',
       '(x<sup>3</sup> &minus; 2 + 1/x<sup>3</sup>)<sup>2</sup> = x<sup>6</sup> + 1/x<sup>6</sup> &minus; 4(x<sup>3</sup> + 1/x<sup>3</sup>) + 6.', 122),

    bq(U, EX3, 'EX5.3', '3', 'What should be added to 4x<sup>4</sup> + 4x<sup>3</sup> + 17x<sup>2</sup> + 8x + 9 to make it a perfect square?', '7',
       '(2x<sup>2</sup> + x + 4)<sup>2</sup> = 4x<sup>4</sup> + 4x<sup>3</sup> + 17x<sup>2</sup> + 8x + 16; we have 9, so add 7.', 122),
    bq(U, EX3, 'EX5.3', '4', 'What should be subtracted from 9x<sup>6</sup> &minus; 12x<sup>5</sup> + 4x<sup>4</sup> &minus; 18x<sup>3</sup> &minus; 12x<sup>2</sup> + 18 to make it a perfect square?', '&minus;24x<sup>2</sup> + 9 (i.e. add 24x<sup>2</sup> &minus; 9)',
       'The perfect square is (3x<sup>3</sup> &minus; 2x<sup>2</sup> &minus; 3)<sup>2</sup> = 9x<sup>6</sup> &minus; 12x<sup>5</sup> + 4x<sup>4</sup> &minus; 18x<sup>3</sup> + 12x<sup>2</sup> + 9; the difference is &minus;24x<sup>2</sup> + 9.', 122),
    bq(U, EX3, 'EX5.3', '5', 'For what value of m is 9x<sup>4</sup> + 12x<sup>3</sup> + 34x<sup>2</sup> + mx + 25 a perfect square?', 'm = 20',
       '(3x<sup>2</sup> + 2x + 5)<sup>2</sup> = 9x<sup>4</sup> + 12x<sup>3</sup> + 34x<sup>2</sup> + 20x + 25, so m = 20.', 122),
    bq(U, EX3, 'EX5.3', '6', 'For what values of p and q is x<sup>4</sup> + 8x<sup>3</sup> + 30x<sup>2</sup> + px + q a perfect square?', 'p = 56, q = 49',
       '(x<sup>2</sup> + 4x + 7)<sup>2</sup> = x<sup>4</sup> + 8x<sup>3</sup> + 30x<sup>2</sup> + 56x + 49, so p = 56 and q = 49.', 122),
    bq(U, EX3, 'EX5.3', '7', 'For what values of a and b is x<sup>4</sup> + 4x<sup>3</sup> + 10x<sup>2</sup> + ax + b a perfect square?', 'a = 12, b = 9',
       '(x<sup>2</sup> + 2x + 3)<sup>2</sup> = x<sup>4</sup> + 4x<sup>3</sup> + 10x<sup>2</sup> + 12x + 9, so a = 12 and b = 9.', 122),
